{"path":"about.html","content":"<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width,initial-scale=1">
  <title>About — {{BUSINESS_NAME}}</title>
  <meta name="description" content="Clinical, confidential therapy in {{CITY}}, {{STATE}} — focused short courses and ongoing sessions." />
  <style>
    :root{--glass-bg:rgba(255,255,255,0.08);--glass-border:rgba(255,255,255,0.12);--accent:#7C6CFF;--muted:#cbd5e1;--card:#0f1724}
    *{box-sizing:border-box}
    html,body{height:100%;margin:0;font-family:system-ui,-apple-system,Segoe UI,Roboto,Helvetica,Arial;background:#0b1220 url('assets/img/pattern.svg') repeat; color:#e6eef8}
    header{backdrop-filter:blur(6px);background:linear-gradient(180deg,rgba(255,255,255,0.02),transparent);border-bottom:1px solid var(--glass-border);position:sticky;top:0;z-index:20}
    .nav{max-width:1100px;margin:0 auto;display:flex;align-items:center;justify-content:space-between;padding:18px}
    .brand{display:flex;align-items:center;gap:12px}
    .logo{width:44px;height:44px;border-radius:10px;background:linear-gradient(135deg,var(--accent),#4ecdc4);display:flex;align-items:center;justify-content:center;font-weight:700;color:#042038}
    nav a{color:var(--muted);text-decoration:none;margin-left:18px;font-size:15px}
    .cta{background:var(--accent);padding:10px 14px;border-radius:8px;color:#021027;text-decoration:none;font-weight:600}
    main{max-width:1100px;margin:34px auto;padding:24px}
    .hero{display:grid;grid-template-columns:1fr 380px;gap:28px;align-items:start}
    .card{background:var(--glass-bg);border:1px solid var(--glass-border);padding:22px;border-radius:14px}
    h1{margin:0 0 8px 0;font-size:28px}
    p.lead{margin:0;color:var(--muted)}
    .sidebar .card{position:sticky;top:86px}
    .section{margin-top:22px}
    .grid{display:grid;grid-template-columns:repeat(2,1fr);gap:12px}
    .benefit{padding:14px;border-radius:10px;background:rgba(255,255,255,0.02);border:1px solid rgba(255,255,255,0.03)}
    footer{opacity:0.9;font-size:13px;color:var(--muted);max-width:1100px;margin:40px auto;padding:18px}

    /* Pricing comparator */
    .comparator{display:flex;align-items:center;gap:12px;padding:12px;border-radius:10px;background:linear-gradient(180deg,rgba(255,255,255,0.02),transparent);border:1px solid var(--glass-border)}
    .toggle{background:rgba(255,255,255,0.03);padding:6px;border-radius:999px;display:flex;align-items:center;gap:6px;width:120px}
    .switch{width:42px;height:24px;background:rgba(0,0,0,0.25);border-radius:999px;padding:3px;cursor:pointer}
    .knob{height:18px;width:18px;background:white;border-radius:50%;transition:transform .28s}
    .knob.month{transform:translateX(0)}
    .knob.package{transform:translateX(18px)}
    .prices{display:flex;gap:12px;align-items:baseline}
    .price{font-weight:700;font-size:20px}
    .note{font-size:13px;color:var(--muted)}

    /* Mood-to-Method */
    .moods{display:flex;gap:10px;flex-wrap:wrap;margin-top:10px}
    .mood{padding:8px 12px;border-radius:12px;background:rgba(255,255,255,0.02);cursor:pointer;border:1px solid transparent}
    .mood.active{background:linear-gradient(90deg,rgba(124,108,255,0.24),rgba(78,205,196,0.12));border-color:rgba(124,108,255,0.18)}
    .approachBox{margin-top:12px;padding:12px;border-radius:10px;background:rgba(255,255,255,0.02);border:1px solid var(--glass-border)}

    /* small */
    @media(max-width:900px){.hero{grid-template-columns:1fr}.sidebar{order:-1}.card{padding:16px}}
  </style>
</head>
<body>
<header>
  <div class="nav">
    <div class="brand"><div class="logo">TP</div><div>
      <div style="font-weight:700">{{BUSINESS_NAME}}</div>
      <div style="font-size:12px;color:var(--muted)">Therapy — {{CITY}}, {{STATE}}</div>
    </div></div>
    <nav>
      <a href="index.html">Start</a>
      <a href="about.html">About</a>
      <a href="specialties.html">Focus Areas</a>
      <a href="approach.html">Method</a>
      <a class="cta" href="{{PRIMARY_CTA_URL}}">{{PRIMARY_CTA_LABEL}}</a>
    </nav>
  </div>
</header>
<main>
  <div class="hero">
    <div>
      <div class="card">
        <h1>About the practice</h1>
        <p class="lead">I offer discreet, evidence-informed therapy designed around short courses and longer collaboration. Sessions respect your pace, boundaries, and confidentiality.</p>
        <div class="section">
          <h3 style="margin:0 0 8px 0">What I emphasize</h3>
          <div class="grid">
            <div class="benefit"><strong>Practical framing</strong>
              <div class="note">Workable steps that fit your daily life — not homework that overwhelms.</div></div>
            <div class="benefit"><strong>Clear goals</strong>
              <div class="note">Goals shaped collaboratively, reviewed each few sessions.</div></div>
            <div class="benefit"><strong>Flexible rhythm</strong>
              <div class="note">Short focused 6-session arcs or ongoing weekly support.</div></div>
            <div class="benefit"><strong>Confidential setting</strong>
              <div class="note">Private practice policies, limits to confidentiality outlined at intake.</div></div>
          </div>
        </div>

        <div class="section">
          <h3 style="margin:0 0 8px 0">Therapeutic boundaries & safety</h3>
          <p class="note">I am a licensed clinician. Conversations are confidential within professional and legal limits. I do not provide emergency services. If you are in crisis or feel unsafe, please contact local emergency services or a crisis line immediately.
          </p>
        </div>
      </div>

      <div class="section">
        <div class="card">
          <h3 style="margin:0 0 8px 0">Mood-to-Method selector</h3>
          <div class="note">Choose the current state that fits. The recommended path and the booking suggestion update to match.</div>
          <div class="moods" role="list">
            <button class="mood" data-key="overwhelmed">Overwhelmed</button>
            <button class="mood" data-key="stuck">Stuck</button>
            <button class="mood" data-key="anxious">Anxious</button>
            <button class="mood" data-key="transition">In transition</button>
            <button class="mood" data-key="curious">Curious / preventative</button>
          </div>
          <div class="approachBox" id="approachBox">
            <strong id="approachTitle">Select a state — see an approach</strong>
            <p id="approachText" class="note" style="margin-top:8px">When you pick one, I'll suggest a way to work together and a next-step booking label.</p>
            <a id="approachCTA" class="cta" href="{{PRIMARY_CTA_URL}}" style="display:inline-block;margin-top:12px">{{PRIMARY_CTA_LABEL}}</a>
          </div>
        </div>
      </div>

    </div>

    <aside class="sidebar">
      <div class="card">
        <h4 style="margin:0 0 8px 0">Programs & investment</h4>
        <p class="note" style="margin-bottom:12px">Two common paths — pick the rhythm that fits your needs.</p>

        <div class="comparator">
          <div style="flex:1">
            <div style="font-size:13px;color:var(--muted)">View</div>
            <div style="font-weight:700">Billing mode</div>
          </div>
          <div class="toggle" role="tablist" aria-label="pricing toggle">
            <div style="font-size:12px;color:var(--muted)">Monthly</div>
            <div class="switch" id="priceSwitch" role="button" aria-pressed="false"><div class="knob month" id="knob"></div></div>
            <div style="font-size:12px;color:var(--muted)">Package</div>
          </div>
        </div>

        <div style="margin-top:12px;display:flex;flex-direction:column;gap:8px">
          <div style="display:flex;justify-content:space-between;align-items:baseline">
            <div class="note">Clarity Sessions</div>
            <div class="price" data-month="140" data-package="760">$140</div>
          </div>
          <div style="display:flex;justify-content:space-between;align-items:baseline">
            <div class="note">Anchor Course (6) — short arc</div>
            <div class="price" data-month="820" data-package="450">$820</div>
          </div>
        </div>
        <div class="note" style="margin-top:10px">Numbers animate when you switch. Exact rate confirmed on intake.</div>
      </div>

      <div class="card" style="margin-top:12px">
        <h4 style="margin:0 0 8px 0">Contact</h4>
        <div class="note">Phone: {{PHONE}}<br/>Email: <a href="mailto:{{EMAIL}}" style="color:var(--muted)">{{EMAIL}}</a></div>
        <a class="cta" href="{{PRIMARY_CTA_URL}}" style="display:inline-block;margin-top:12px">Book a first call</a>
      </div>
    </aside>
  </div>

  <div class="section">
    <div class="card">
      <h3 style="margin:0 0 8px 0">How sessions typically proceed</h3>
      <ol class="note" style="margin:0 0 0 18px">
        <li>Brief intake to clarify your priorities and check fit.</li>
        <li>Set a focused goal or choose a short arc (if you prefer a clear endpoint).</li>
        <li>Review progress every 4–6 sessions and adjust pace or approach.</li>
      </ol>
    </div>
  </div>

</main>
<footer>
  <div>Confidentiality: records are private within professional and legal limits. Scope: I do not provide emergency services. If you are in immediate danger or crisis, please call emergency services or your local crisis line.</div>
</footer>

<script>
// Pricing comparator logic
(function(){
  const switchEl = document.getElementById('priceSwitch');
  const knob = document.getElementById('knob');
  const prices = Array.from(document.querySelectorAll('.price'));
  let mode = 'monthly'; // monthly or package

  function animateValue(el, start, end, duration){
    let startTime = null;
    const step = (timestamp)=>{
      if(!startTime) startTime = timestamp;
      const progress = Math.min((timestamp-startTime)/duration,1);
      const value = Math.round(start + (end-start)*progress);
      el.textContent = '$' + value;
      if(progress < 1) requestAnimationFrame(step);
    };
    requestAnimationFrame(step);
  }

  switchEl.addEventListener('click', ()=>{
    mode = (mode === 'monthly') ? 'package' : 'monthly';
    switchEl.setAttribute('aria-pressed', mode==='package');
    knob.classList.toggle('package', mode==='package');
    knob.classList.toggle('month', mode==='monthly');
    prices.forEach(p=>{
      const month = parseInt(p.getAttribute('data-month'));
      const pack = parseInt(p.getAttribute('data-package'));
      const from = parseInt(p.textContent.replace('$',''))||0;
      const to = (mode==='monthly') ? month : pack;
      animateValue(p, from, to, 480);
    });
  });
})();

// Mood-to-Method logic
(function(){
  const mapping = {
    overwhelmed: {title:'Stabilize & simplify', text:'Short stabilizing steps: identify immediate stressors, set small behaviors to reduce overwhelm, and practice simple grounding routines. Good for when daily life feels flooded.', cta:'Book a stabilizing session'},
    stuck: {title:'Clarify stuck points', text:'Work to name the pattern keeping you stuck, test small experiments, and design a brief plan to move forward. Often a 4–8 session arc brings clarity.', cta:'Start a clarity arc'},
    anxious: {title:'Skill & exposure work', text:'We focus on manageable exposure and skills training to reduce avoidance and rebuild confidence in manageable increments.', cta:'Schedule an anxiety session'},
    transition: {title:'Transition mapping', text:'Map through roles, values, and practical choices to make decisions easier and less draining. Useful during career, relationship, or family changes.', cta:'Plan a transition conversation'},
    curious: {title:'Preventive check-ins', text:'Short, periodic sessions to keep perspective and refresh skills. A good fit if you want to stay steady and proactive.', cta:'Book a maintenance session'}
  };

  const moodButtons = Array.from(document.querySelectorAll('.mood'));
  const titleEl = document.getElementById('approachTitle');
  const textEl = document.getElementById('approachText');
  const ctaEl = document.getElementById('approachCTA');

  moodButtons.forEach(btn=>{
    btn.addEventListener('click', ()=>{
      moodButtons.forEach(b=>b.classList.remove('active'));
      btn.classList.add('active');
      const key = btn.getAttribute('data-key');
      const info = mapping[key];
      titleEl.textContent = info.title;
      textEl.textContent = info.text;
      ctaEl.textContent = info.cta + ' — ' + '{{PRIMARY_CTA_LABEL}}';
    });
  });
})();
</script>
</body>
</html>"} 
