<body>
<header>
  <div class="nav">
    <div style="display:flex;align-items:center;gap:12px">
      <div style="width:44px;height:44px;border-radius:10px;background:#7c6cff"></div>
      <div style="font-weight:700">{{BUSINESS_NAME}}</div>
