          <div style="display:flex;justify-content:space-between"><div class="muted">Short Course — 6 sessions</div><div class="price2" data-month="840" data-package="520">$840</div></div>
          <div style="display:flex;justify-content:space-between"><div class="muted">Ongoing weekly</div><div class="price2" data-month="560" data-package="300">$560</div></div>
