<script>
// pricing toggle for specialties
(function(){
  const s = document.getElementById('switch2');
  const k = document.getElementById('knob2');
  const els = Array.from(document.querySelectorAll('.price2'));
  let mode = 'monthly';
  function update(toMode){
    els.forEach(e=>{
      const m = parseInt(e.getAttribute('data-month'));
      const p = parseInt(e.getAttribute('data-package'));
      const target = toMode==='monthly'?m:p;
      e.textContent = '$' + target;
    });
  }
  s.addEventListener('click', ()=>{
    mode = mode==='monthly'?'package':'monthly';
    s.setAttribute('aria-pressed', mode==='package');
    k.classList.toggle('right', mode==='package');
    k.classList.toggle('left', mode==='monthly');
    update(mode);
  });
  update(mode);
})();

// mood quick match
(function(){
  const map = {
    confused:{title:'Map options',text:'We slow down the decision process and list manageable next steps.',cta:'Plan a mapping session'},
    pressed:{title:'Short stabilizing arc',text:'Three focused sessions to ease pressure and make a practical plan.',cta:'Book a short arc'},
    planning:{title:'Design session',text:'Translate goals into sequential actions and checkpoints.',cta:'Schedule a design session'}
  };
  const buttons = Array.from(document.querySelectorAll('.m2'));
  buttons.forEach(b=>b.addEventListener('click', ()=>{
    buttons.forEach(x=>x.disabled=false); b.disabled=true;
    const key=b.getAttribute('data-key');
    const info=map[key];
    document.getElementById('methodTitle').textContent=info.title;
    document.getElementById('methodText').textContent=info.text;
    document.getElementById('methodCTA').textContent=info.cta + ' — ' + '{{PRIMARY_CTA_LABEL}}';
  }));
})();
</script>
</body>
</html>"} 
{"path":"approach.html","content":"<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width,initial-scale=1">
  <title>How I work — {{BUSINESS_NAME}}</title>
  <meta name="description" content="Therapeutic approach and process — collaborative, evidence-informed, tailored to what you need now." />
  <style>
    :root{--bg:#041018;--glass:rgba(255,255,255,0.04);--accent:#7C6CFF;--muted:#a9c0d9}
    html,body{height:100%;margin:0;font-family:system-ui,Segoe UI,Roboto,Arial;background:radial-gradient(circle at 10% 10%,#071b2a,transparent 20%),url('assets/img/pattern.svg');color:#eaf4ff}
    header{padding:12px 18px;background:linear-gradient(180deg,rgba(255,255,255,0.02),transparent);backdrop-filter:blur(4px);border-bottom:1px solid rgba(255,255,255,0.03)}
    .nav{max-width:1100px;margin:0 auto;display:flex;justify-content:space-between;align-items:center}
    .nav a{color:var(--muted);text-decoration:none;margin-left:12px}
    .cta{background:var(--accent);color:#032; padding:8px 11px;border-radius:9px;text-decoration:none}
    main{max-width:1100px;margin:28px auto;padding:22px}

    .leadCard{background:var(--glass);padding:18px;border-radius:14px;border:1px solid rgba(255,255,255,0.04)}
    h1{margin:0 0 6px 0}
    .steps{display:flex;gap:12px;margin-top:14px}
    .step{flex:1;padding:12px;border-radius:10px;background:linear-gradient(180deg,rgba(255,255,255,0.02),transparent);border:1px solid rgba(255,255,255,0.03)}
    .muted{color:var(--muted)}

