<script>
// switch3 simple toggle
(function(){
  const sw = document.getElementById('switch3');
  const knob = document.getElementById('knob3');
  const prices = Array.from(document.querySelectorAll('.p3'));
  let mode='monthly';
  function update(m){
    prices.forEach(p=>{
      p.textContent = '$' + (m==='monthly'?p.getAttribute('data-month'):p.getAttribute('data-package'));
    });
  }
  sw.addEventListener('click', ()=>{
    mode = mode==='monthly'?'package':'monthly';
    sw.setAttribute('aria-pressed', mode==='package');
    if(mode==='package'){knob.style.transform='translateX(22px)';} else {knob.style.transform='translateX(0)';}
    update(mode);
  });
  update(mode);
})();

// mood-to-method full mapping
(function(){
  const map = {
    flat:{title:'Re-engagement plan',text:'Gentle activation: small behavioural steps to reconnect with things that matter, with attention to energy management.',cta:'Book a re-engagement session'},
    angry:{title:'Contain & reflect',text:'We work on naming triggers, setting limits, and redirecting energy into problem-solving strategies.',cta:'Schedule a containment session'},
    risky:{title:'Support through change',text:'A balance of practical planning and emotion regulation to reduce impulse and protect values during big steps.',cta:'Plan a support series'},
    relational:{title:'Relation-focused work',text:'Identify interaction patterns, practice new responses, and map safe experiments to change dynamics.',cta:'Start relationship work'},
    maintenance:{title:'Maintenance check-ins',text:'Short check-ins to sustain progress and troubleshoot when old patterns reappear.',cta:'Book a check-in'}
  };
  const buttons = Array.from(document.querySelectorAll('.mFull'));
  const h = document.getElementById('methodH');
  const p = document.getElementById('methodP');
  const cta = document.getElementById('methodBook');
  buttons.forEach(b=>{
    b.addEventListener('click', ()=>{
      buttons.forEach(x=>x.classList.remove('active'));
      b.classList.add('active');
      const key = b.getAttribute('data-key');
      const info = map[key];
      h.textContent = info.title;
      p.textContent = info.text;
      cta.textContent = info.cta + ' — ' + '{{PRIMARY_CTA_LABEL}}';
      // subtle visual morph
      cta.style.transform = 'scale(0.98)';
      setTimeout(()=>cta.style.transform='scale(1)',160);
    });
  });
})();
</script>
